<div class="mb-3"><a href="<?= url('admin/empleados/nuevo') ?>" class="btn btn-mi"><i class="bi bi-person-plus"></i> Nuevo empleado</a></div>
<div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Nombre</th><th>Correo</th><th>Teléfono</th><th>Último acceso</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody>
<?php foreach ($emps as $m): ?><tr><td><b><?= e($m['nombre']) ?></b><br><small class="text-muted">Doc. <?= e($m['documento']) ?></small></td><td><?= e($m['correo']) ?></td><td><?= e($m['telefono']) ?></td><td><?= $m['ultimo_acceso'] ? fecha($m['ultimo_acceso'], true) : '—' ?></td>
<td><span class="badge text-bg-<?= $m['estado'] === 'activo' ? 'success' : 'secondary' ?>"><?= e(ucfirst($m['estado'])) ?></span></td>
<td class="text-end"><div class="d-inline-flex gap-1"><a class="btn btn-sm btn-outline-mi" href="<?= url('admin/empleados/' . (int) $m['id_usuario'] . '/editar') ?>"><i class="bi bi-pencil"></i></a>
<form method="post" action="<?= url('admin/empleados/' . (int) $m['id_usuario'] . '/estado') ?>"><?= csrf_field() ?><input type="hidden" name="estado" value="<?= $m['estado'] === 'activo' ? 'inactivo' : 'activo' ?>"><button class="btn btn-sm btn-outline-secondary"><?= $m['estado'] === 'activo' ? 'Desactivar' : 'Activar' ?></button></form>
<form method="post" action="<?= url('admin/empleados/' . (int) $m['id_usuario'] . '/clave') ?>" onsubmit="return confirm('Se generará una nueva contraseña temporal. ¿Continuar?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-secondary" title="Nueva contraseña temporal"><i class="bi bi-key"></i></button></form></div></td></tr><?php endforeach; ?>
